#include <iostream>
#include <cstdlib>
using namespace std;

long long nod(long long a, long long b)
{
    a = llabs(a);
    b = llabs(b);
    while (b != 0)
    {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main()
{
    long long a1, a2, b1, b2, c1, c2;
    cin >> a1 >> b1 >> c1 >> a2 >> b2 >> c2;

    if (a1 < 0 || (a1 == 0 && b1 < 0))
    {
        a1 = -a1;
        b1 = -b1;
        c1 = -c1;
    }

    if (a2 < 0 || (a2 == 0 && b2 < 0))
    {
        a2 = -a2;
        b2 = -b2;
        c2 = -c2;
    }

    if ((a1 == 0 && b1 == 0 && c1 != 0) ||
        (a2 == 0 && b2 == 0 && c2 != 0))
    {
        cout << 0 << '\n';
        return 0;
    }

    if ((a1 == 0 && b1 == 0 && c1 == 0) ||
        (a2 == 0 && b2 == 0 && c2 == 0))
    {
        cout << -1 << '\n';
        return 0;
    }

    if (b1 == 0 && b2 == 0)
    {
        cout << (a1 == a2 && c1 == c2 ? -1 : 0) << '\n';
        return 0;
    }

    if (a1 == 0 && a2 == 0)
    {
        cout << (b1 == b2 && c1 == c2 ? -1 : 0) << '\n';
        return 0;
    }

    long long d1 = nod(a1, nod(b1, c1));
    long long d2 = nod(a2, nod(b2, c2));

    a1 /= d1;
    b1 /= d1;
    c1 /= d1;

    a2 /= d2;
    b2 /= d2;
    c2 /= d2;

    if (a1 == a2 && b1 == b2 && c1 == c2)
        cout << -1 << '\n';
    else if (a1 == a2 && b1 == b2)
        cout << 0 << '\n';
    else
        cout << 1 << '\n';

    return 0;
}

